const assistantMessage = firstChoice.message;
const actionsList = await processUnifiedAgentToolCalls({
  actions: this.actions,
  ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
  assistantMessage,
  contactId,
  ...(context !== undefined ? { context } : {}),
  executeTools: context?.executeTools !== false,
  logger: this.logger,
  phone,
  toolRouterDeps: this.toolRouterDeps,
  workspaceId,
});
